 for(const change of ["source","authority"] as const){const command=key(),fault=`asset_final_${key().replaceAll('-','')}`,effect=change==="source"?`UPDATE operational_assets SET condition='unsafe' WHERE id='${id}'`:`UPDATE assignments SET revoked_at=1,version=version+1 WHERE id='${f.owner.assignmentId}'`,before=await snapshot();await db.exec(`CREATE FUNCTION ${fault}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN ${effect};RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${fault} AFTER INSERT ON audit_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.command_id='${command}') EXECUTE FUNCTION ${fault}()`);try{await expect(changeAsset(f.owner,id,input,command)).rejects.toMatchObject({code:change==="source"?"ASSETS_SOURCE_CHANGED":"ASSETS_ACCESS_CHANGED"});expect(await snapshot()).toEqual(before);}finally{await db.exec(`DROP TRIGGER ${fault} ON audit_events;DROP FUNCTION ${fault}()`);}}
