    const context:AssetsFixtureWorkContext={userId,assignmentId,role,companyId:company,branchId:scopeKind==='holding'?null:branch,departmentId:scopeKind==='department'?department:null,holdingId:'h001',holdingSlug:'assets-test',holdingName:'Test',name,email:`${name}@example.test`,assignmentScope:scopeKind,inherited:false,modules:role.startsWith('finance_')||role==='auditor'?[]:['assets'],assignments:[],workspaces:[],scope};
